import net.officefloor.hq.app.rollup.RollupBefore;

/** A transfer once checked: the person transferred (who leaves their sheet), the sheet they go to, who transfers them,
 *  and the other sheet's figures before it (the sheet they leave takes its own, see TakeRollup). */
public record PersonTransfer(Person person, String toSheet, String by, RollupBefore toBefore) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.claim.ClaimNumbering;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores the transfer (see PersonTransferrer#transfer), then gives each moved claim that had a number the next number
 *  of the other sheet (see ClaimNumbering), in the order the claims were opened. */
public class TransferPerson {
    public void transfer(@Val PersonTransfer transfer, PersonTransferrer transferrer, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets) {
        String to = transfer.toSheet();
        for (long id : transferrer.transfer(transfer.person(), to)) {
            claims.renumber(claims.find(to, id), ClaimNumbering.next(claims.find(to, id), claims, periods, settings, sheets));
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_TRANSFERRED name=<name> to=<sheet> on the sheet the person left, then that sheet's figures the transfer
 *  moved (see Rollup), then PERSON_TRANSFERRED name=<name> from=<sheet> on the sheet they went to, then that sheet's. */
public class RecordPersonTransferred {
    public void record(@Val PersonTransfer transfer, @Val RollupBefore before, Rollup rollup, Audit audit) {
        String from = transfer.person().sheetId();
        String to = transfer.toSheet();
        String name = transfer.person().name();
        audit.record("PERSON_TRANSFERRED sheet=" + from + " by=" + transfer.by() + " name=" + name + " to=" + to);
        rollup.record(from, transfer.by(), before);
        audit.record("PERSON_TRANSFERRED sheet=" + to + " by=" + transfer.by() + " name=" + name + " from=" + from);
        rollup.record(to, transfer.by(), transfer.toBefore());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: a transfer names the sheet the person goes to and the signed-in user. */
public class ValidateTransfer {
    public void validate(@RequestBody TransferRequest request, Out<TransferRequest> body) throws InvalidPersonException {
        String to = request == null || request.toSheet() == null ? "" : request.toSheet().trim();
        if (to.isEmpty()) {
            throw new InvalidPersonException("A transfer needs the sheet transferred to");
        }
        String by = request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidPersonException("The user transferring is required");
        }
        body.set(new TransferRequest(to, by));
    }
}
package net.officefloor.hq.app.person;

/** Body of transferring a person to another sheet: the id of the sheet they go to, and who transfers them. */
public record TransferRequest(String toSheet, String by) {
}
